#root,[data-workspace-area='conversation'],.messages-timeline-scroll,[data-settings-page-scroll]{background:transparent !important}
[data-slot='sidebar-inner'],[data-chat-header],[data-thread-details-card],[data-thread-terminal-drawer],[data-user-message-bubble],.chat-markdown-codeblock,[data-slot='dialog-popup'],[data-slot='popover-popup'],[data-slot='menu-popup'],[data-slot='tooltip-popup'],[data-slot='select-trigger'],[data-slot='input']{-webkit-backdrop-filter:blur(18px) saturate(1.3) !important;backdrop-filter:blur(18px) saturate(1.3) !important}
[data-slot='dialog-popup'],[data-slot='popover-popup'],[data-slot='menu-popup']{-webkit-backdrop-filter:blur(28px) saturate(1.4) !important;backdrop-filter:blur(28px) saturate(1.4) !important}
[data-slot='composer-shell']::before,[data-slot='composer-host']::before,[data-slot='composer-context-strip']::before{display:none !important}
[data-slot='composer-host']{background:rgb(6 6 6/72%) !important;-webkit-backdrop-filter:blur(20px) saturate(1.3) !important;backdrop-filter:blur(20px) saturate(1.3) !important}
[data-slot='composer-context-strip']{background:transparent !important;-webkit-backdrop-filter:none !important;backdrop-filter:none !important;box-shadow:none !important;border-color:transparent !important}
[data-changed-files-state]{background:rgb(8 8 8/62%) !important;border:1px solid rgb(255 255 255/6%) !important;-webkit-backdrop-filter:blur(20px) saturate(1.3) !important;backdrop-filter:blur(20px) saturate(1.3) !important}
[data-changed-files-header]{background:transparent !important;-webkit-backdrop-filter:blur(16px) !important;backdrop-filter:blur(16px) !important;border-bottom:1px solid rgb(255 255 255/5%)}
[data-slot='switch-thumb']{background:#0a0a0a !important}
[data-slot='command-dialog-popup']{background:rgb(6 6 6/78%) !important;-webkit-backdrop-filter:blur(24px) saturate(1.3) !important;backdrop-filter:blur(24px) saturate(1.3) !important}
[data-thread-terminal-drawer]{background:rgb(10 10 10/42%) !important;-webkit-backdrop-filter:blur(22px) saturate(1.3) !important;backdrop-filter:blur(22px) saturate(1.3) !important}
[data-thread-terminal-drawer] [class*='bg-(--terminal-background)']{background:transparent !important}
[data-thread-terminal-drawer] canvas{mix-blend-mode:screen}
.chat-markdown a,[data-user-message-bubble] a,[data-user-message-bubble] [class*='underline'],.composer-tiptap a,.composer-tiptap [contenteditable='false'],.composer-tiptap [contenteditable='false'] *{color:#ff8a42 !important;text-decoration-color:rgb(255 138 66/45%) !important}
.chat-markdown a:hover,[data-user-message-bubble] a:hover,[data-user-message-bubble] [class*='underline']:hover,.composer-tiptap a:hover,.composer-tiptap [contenteditable='false']:hover,.composer-tiptap [contenteditable='false']:hover *{color:#ffa067 !important;text-decoration-color:#ffa067 !important}
[data-slot='dialog-popup'],[data-slot='alert-dialog-popup']{background:rgb(6 6 6/78%) !important;-webkit-backdrop-filter:blur(24px) saturate(1.3) !important;backdrop-filter:blur(24px) saturate(1.3) !important}
[data-slot$='dialog-footer']{background:rgb(0 0 0/28%) !important;border-color:rgb(255 255 255/6%) !important}
